//! `ferrobridge suggest`: a `ferrobridge.toml` draft for the places that need annotations.
//!
//! All values in the draft are **comments**. ferrobridge does not guess ownership
//! (safety rule 1); the user enables each line knowing the C++ library. For the item of a line
//! that is not enabled, code is still not generated.

use std::fmt::Write as _;

use crate::config::ReturnAnnotation;
use crate::plan::{BridgePlan, Suggestion, SuggestionTarget};

const HEADER: &str = "\
# ferrobridge.toml draft (generated by `ferrobridge suggest`).
#
# Every annotation is a PROMISE you make about the C++ library. If the promise is wrong, the generated
# code can cause undefined behavior. Remove the `# ` at the start of the lines you are sure of;
# leave the ones you are not sure of commented out, and no code is generated for them.
#
#   borrowed (parameter): the pointer/reference points to a single object (not an array), is not
#                         null, and is used only during the call and not kept.
#   { slice = \"n\" } (parameter): the pointer points to an array with as many elements as parameter `n`
#                         and is used only during the call; in Rust the two become a single
#                         `&[T]`. Enable only one line for the same parameter.
#   owned    (return):    the pointer was allocated with `new`; deleting it is up to the caller.
#   borrowed (return):    the pointer/reference points to something the object owns and is
#                         valid while the object lives (methods only).
#
# If your file already has the same table, move the lines under that table.
";

/// Merged suggestions for a key (overloads share the same key).
struct Group<'p> {
    key: &'p str,
    signatures: Vec<(&'p str, String)>,
    returns: Vec<(ReturnAnnotation, &'p str)>,
    /// (name, C++ type, candidate slice lengths)
    params: Vec<(&'p str, &'p str, &'p [String])>,
}

/// Turns the plan's suggestions into a commented-out TOML draft. If there are no suggestions,
/// a one-line comment saying so is returned.
pub fn render_suggestions(plan: &BridgePlan) -> String {
    if plan.suggestions.is_empty() {
        return "# Nothing needs an annotation.\n".to_owned();
    }
    let groups = group(&plan.suggestions);
    let mut out = String::from(HEADER);
    for group in groups {
        out.push('\n');
        for (signature, location) in &group.signatures {
            let _ = writeln!(out, "# {signature}  ({location})");
        }
        let key = toml_key(group.key);
        if !group.returns.is_empty() {
            let _ = writeln!(out, "[functions.{key}]");
            for (option, cpp_type) in &group.returns {
                let _ = writeln!(out, "# returns = \"{option}\"  # return: {cpp_type}");
            }
        }
        if !group.params.is_empty() {
            let _ = writeln!(out, "[functions.{key}.params]");
            for (name, cpp_type, lengths) in &group.params {
                let key = toml_key(name);
                let _ = writeln!(out, "# {key} = \"borrowed\"  # {cpp_type}");
                for len in *lengths {
                    let _ = writeln!(
                        out,
                        "# {key} = {{ slice = \"{len}\" }}  # {name}, an array of {len} elements"
                    );
                }
            }
        }
    }
    out
}

fn group(suggestions: &[Suggestion]) -> Vec<Group<'_>> {
    let mut groups: Vec<Group<'_>> = Vec::new();
    for suggestion in suggestions {
        let index = match groups.iter().position(|g| g.key == suggestion.key) {
            Some(index) => index,
            None => {
                groups.push(Group {
                    key: &suggestion.key,
                    signatures: Vec::new(),
                    returns: Vec::new(),
                    params: Vec::new(),
                });
                groups.len() - 1
            }
        };
        let group = &mut groups[index];
        let location = format!("{}:{}", suggestion.location.file, suggestion.location.line);
        if !group
            .signatures
            .iter()
            .any(|(s, _)| *s == suggestion.signature)
        {
            group.signatures.push((&suggestion.signature, location));
        }
        match &suggestion.target {
            SuggestionTarget::Return { options } => {
                for option in options {
                    if !group.returns.iter().any(|(o, _)| o == option) {
                        group.returns.push((*option, &suggestion.cpp_type));
                    }
                }
            }
            SuggestionTarget::Param {
                name,
                slice_lengths,
            } => {
                if !group.params.iter().any(|(n, _, _)| n == name) {
                    group
                        .params
                        .push((name, &suggestion.cpp_type, slice_lengths));
                }
            }
        }
    }
    groups
}

/// A TOML key: as is if it can be a bare key, quoted otherwise.
fn toml_key(key: &str) -> String {
    let bare = !key.is_empty()
        && key
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-');
    if bare {
        key.to_owned()
    } else {
        format!("\"{}\"", key.replace('\\', "\\\\").replace('"', "\\\""))
    }
}
